// frontend/src/components/Navbar.jsx

import React from "react";
import { NavLink } from "react-router-dom";
import TraderSearch from "./TraderSearch";

const links = [
  { to: "/",             label: "🏠 Dashboard" },
  { to: "/fraud",        label: "🚨 Fraud Analysis" },
  { to: "/transactions", label: "📋 Transactions" },
  { to: "/stocks",       label: "📈 Stocks" },
];

export default function Navbar() {
  return (
    <nav
      style={{
        background: "#0f172a",
        borderBottom: "1px solid #1e293b",
        padding: "0 24px",
        display: "flex",
        alignItems: "center",
        gap: "4px",
        height: "56px",
      }}
    >
      {/* Logo */}
      <span
        style={{
          fontWeight: "bold",
          fontSize: "1.1rem",
          marginRight: "24px",
          color: "#38bdf8",
        }}
      >
        🕶️ TraceNet
      </span>

      {/* Navigation Links */}
      {links.map((l) => (
        <NavLink
          key={l.to}
          to={l.to}
          end
          style={({ isActive }) => ({
            padding: "8px 16px",
            borderRadius: "6px",
            textDecoration: "none",
            color: isActive ? "#38bdf8" : "#94a3b8",
            background: isActive
              ? "rgba(56,189,248,0.1)"
              : "transparent",
            fontWeight: isActive ? "bold" : "normal",
            fontSize: "0.9rem",
          })}
        >
          {l.label}
        </NavLink>
      ))}

      {/* 🔍 Trader Search (pushed to right) */}
      <div style={{ marginLeft: "auto" }}>
        <TraderSearch />
      </div>
    </nav>
  );
}
